(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18+Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.02-t*0.27)*16+Math.sin(x*0.016+t*0.33)*11;
  const w2x = Math.sin(x*0.009+t*0.15)*25+Math.cos(y*0.011-t*0.12)*20;
  const w2y = Math.cos(y*0.008+t*0.18)*22+Math.sin(x*0.012-t*0.14)*18;
  const sx = x+w1x+w2x*0.5, sy = y+w1y+w2y*0.5;
  const src = [
    [160+Math.sin(t*0.6)*110, 80+Math.cos(t*0.4)*55, 0.075, 2.1],
    [320+Math.cos(t*0.5)*105, 160+Math.sin(t*0.7)*55, 0.095, 1.8],
    [240+Math.sin(t*0.3+2)*150, 120+Math.cos(t*0.5+1)*95, 0.055, 2.4],
    [120+Math.cos(t*0.8+1)*85, 180+Math.sin(t*0.6+3)*65, 0.11, 1.6],
    [360+Math.sin(t*0.4+4)*95, 60+Math.cos(t*0.9+2)*75, 0.065, 2.7],
    [240+Math.cos(t*0.35+5)*130, 200+Math.sin(t*0.55)*85, 0.085, 2.0],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.1, 1.4],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*55, 0.07, 2.2]
  ];
  let aS=0,iS=0,cS=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w=Math.sin(d*0.02+t*0.5)*0.15+1;
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.65+t*sp*0.55+1.7)*w;
    cS+=Math.sin(d*f*1.3-t*sp*0.8+3.0)*w*0.4;
  }
  const n=8,act=aS/n,inh=iS/n,cou=cS/n;
  const bg=(Math.sin(sx*0.035+sy*0.022+t*0.75)+Math.sin(sx*0.028-sy*0.038+t*1.05))/2
    +Math.sin((sx+sy)*0.11+t*2.3)*0.18+Math.sin((sx-sy)*0.09-t*1.9)*0.18
    +Math.sin(sx*0.065+t*1.7)*Math.cos(sy*0.055-t*1.3)*0.12;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.6)+Math.sin(dist*0.038+ang*4.5-t*1.25)+Math.sin(dist*0.06-ang*2-t*2.1))*0.3;
  const voronoi=()=>{
    let md=1e9,md2=1e9;
    for(let i=0;i<12;i++){
      const a=i*0.5236+t*0.12*(i%2?1:-1);
