      const px=cx+Math.cos(a)*r,py=cy+Math.sin(a)*r;
      const d=Math.sqrt((sx-px)**2+(sy-py)**2);
      if(d<md){md2=md;md=d;}else if(d<md2)md2=d;
    }
    return(md2-md)*0.08;
  };
  const vEdge=voronoi();
  const reaction=Math.tanh((act-inh*0.65+bg*0.28+spiral*0.35+cou*0.2+vEdge)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.45+Math.sin(sx*0.08-sy*0.06+t*0.7)*0.3)*1.4)*0.28;
  const micro=Math.sin(sx*0.3+t*3)*Math.sin(sy*0.35-t*2.5)*0.04;
  const glow=Math.exp(-dist*0.008)*0.15*Math.sin(t*0.8)*reaction;
  const blend=reaction*0.6+cell*0.2+glow*0.1+micro,v=blend*0.5+0.5;
  const pal=[
    [6,12,52],[12,42,88],[18,82,118],[24,128,128],[45,158,115],
    [120,175,90],[195,185,65],[215,155,55],[210,115,65],[185,70,72],
    [140,38,68],[85,18,55],[40,12,45],[6,12,52]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const sm=f*f*(3-2*f);
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.65?1.12+Math.abs(reaction)*0.08:1.0;
  const shimmer=Math.sin(sx*0.08+sy*0.06+t*4)*0.03+1;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*lum*edge*shimmer)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*sm)*lum*edge*shimmer)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*sm)*lum*edge*shimmer)|0
  ];
}
